class Solution {
public:
    vector<int> threeEqualParts(vector<int>& arr) {
        int total = 0;
        for (int x : arr) total += x;
        if (total % 3 != 0) return {-1, -1};
        if (total == 0) return {0, (int)arr.size() - 1};
        int k = total / 3;
        int p1 = -1, p2 = -1, p3 = -1, cnt = 0;
        for (int i = 0; i < (int)arr.size(); i++) {
            if (arr[i] == 1) {
                cnt++;
                if (cnt == 1) p1 = i;
                else if (cnt == k + 1) p2 = i;
                else if (cnt == 2 * k + 1) p3 = i;
            }
        }
        while (p3 < (int)arr.size()) {
            if (arr[p1] != arr[p2] || arr[p2] != arr[p3]) return {-1, -1};
            p1++; p2++; p3++;
        }
        return {p1 - 1, p2};
    }
};

