var threeEqualParts = function(arr) {
    let total = 0;
    for (const x of arr) total += x;
    if (total % 3 !== 0) return [-1, -1];
    if (total === 0) return [0, arr.length - 1];
    const k = total / 3;
    let p1 = -1, p2 = -1, p3 = -1, cnt = 0;
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === 1) {
            cnt++;
            if (cnt === 1) p1 = i;
            else if (cnt === k + 1) p2 = i;
            else if (cnt === 2 * k + 1) p3 = i;
        }
    }
    while (p3 < arr.length) {
        if (arr[p1] !== arr[p2] || arr[p2] !== arr[p3]) return [-1, -1];
        p1++; p2++; p3++;
    }
    return [p1 - 1, p2];
};
